    assert len(sonuc) == 3
    assert sonuc == [33.33, 33.33, 33.34]
    assert round(sum(sonuc), 2) == round(100.0, 2)
    for v in sonuc:
        assert v == round(v, 2)

def test_yuvarlama_genel():
    sonuc = esit_taksit(999.99, 7)
    assert len(sonuc) == 7
    assert round(sum(sonuc), 2) == round(999.99, 2)
    for v in sonuc:
        assert v == round(v, 2)
    assert sonuc[0] == sonuc[1] == sonuc[2] == sonuc[3] == sonuc[4] == sonuc[5]

def test_kucuk_toplam():
    sonuc = esit_taksit(1.0, 12)
